import { useState } from 'react';

// ❌ OLD: Every setCount re-executes the ENTIRE component function:
// all children re-render (unless memoized), all expressions re-run,
// and the Virtual DOM diffs the result.
function Counter() {
  const [count, setCount] = useState(0); // ❌ OLD: coarse-grained state

  // Re-runs on every count change even though it never reads count:
  const expensive = computeExpensiveThing(); // ❌ OLD: wasted work

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(c => c + 1)}>+1</button>
      <Child prop={expensive} /> {/* re-rendered too */}
    </div>
  );
}

import { createSignal } from 'solid-js';

// ✅ NEW: setCount re-runs ONLY the JSX expressions (or effects) that
// actually read count(). The component function runs once; the
// template is compiled into fine-grained computation nodes.
function Counter() {
  const [count, setCount] = createSignal(0); // ✅ NEW: getter + setter

  // Runs once (no signal read here), NOT on every count change:
  const expensive = computeExpensiveThing(); // ✅ NEW: not re-executed

  return (
    <div>
      <p>Count: {count()}</p> {/* ✅ NEW: this node alone re-runs */}
      <button onClick={() => setCount(c => c + 1)}>+1</button>
      <Child prop={expensive} /> {/* not re-created on count change */}
    </div>
  );
}
